import tallgrass.Font;
import tallgrass.PixelCanvas;

import javax.imageio.ImageIO;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.ArrayList;
import java.util.List;

/**
 * HD art proposal. Renders a sample town scene at 480x320 with 32x32 tiles, the texture atlas it is built
 * from, and a side-by-side with the current GBA look.
 *
 * Every texture is still generated by code, but it is *baked* into PNG sprites first, the way Minecraft
 * ships one texture per block. The game would then load those sprites from a texture pack folder, so they
 * could also be hand-edited or replaced.
 */
public class HdProposal {
    static final int T = 32, W = 15 * T, H = 10 * T;
    static final double LX = -0.5, LY = -0.68, LZ = 0.54;

    // ------------------------------------------------------------ color helpers (24-bit, no GBA snapping)

    static int[] ramp(int rgb, int n) {
        float[] hsb = Color.RGBtoHSB((rgb >> 16) & 255, (rgb >> 8) & 255, rgb & 255, null);
        int[] out = new int[n];
        int mid = n / 2;
        for (int i = 0; i < n; i++) {
            double k = (i - mid) / (double) mid;
            double h = hsb[0], s = hsb[1], b = hsb[2];
            if (k < 0) { h = toward(h, .66, -k * .08); s = Math.min(1, s - k * .14); b *= 1 + k * .5; }
            else if (k > 0) { h = toward(h, .14, k * .06); s = Math.max(0, s - k * .2); b = Math.min(1, b + (1 - b) * k * .55 + k * .05); }
            out[i] = 0xff000000 | (Color.HSBtoRGB((float) h, (float) s, (float) b) & 0xffffff);
        }
        return out;
    }

    static double toward(double h, double t, double a) {
        double d = ((t - h + 1.5) % 1.0) - .5;
        return (((h + d * Math.min(1, a * 4)) % 1.0) + 1.0) % 1.0;
    }

    static int sh(int[] r, double v) { return r[(int) Math.max(0, Math.min(r.length - 1, Math.round(v)))]; }

    static int mix(int a, int b, double t) {
        t = Math.max(0, Math.min(1, t));
        int r = (int) (((a >> 16) & 255) * (1 - t) + ((b >> 16) & 255) * t);
        int g = (int) (((a >> 8) & 255) * (1 - t) + ((b >> 8) & 255) * t);
        int bl = (int) ((a & 255) * (1 - t) + (b & 255) * t);
        return 0xff000000 | r << 16 | g << 8 | bl;
    }

    static void px(BufferedImage im, int x, int y, int c) { if (x >= 0 && y >= 0 && x < im.getWidth() && y < im.getHeight()) im.setRGB(x, y, c); }

    static void blend(BufferedImage im, int x, int y, int c, double a) {
        if (x < 0 || y < 0 || x >= im.getWidth() || y >= im.getHeight() || a <= 0) return;
        int base = im.getRGB(x, y);
        if ((base >>> 24) == 0) { im.setRGB(x, y, ((int) (Math.min(1, a) * 255) << 24) | (c & 0xffffff)); return; }
        im.setRGB(x, y, (base & 0xff000000) | (mix(base, c, a) & 0xffffff));
    }

    static void rect(BufferedImage im, int x, int y, int w, int h, int c) { for (int yy = y; yy < y + h; yy++) for (int xx = x; xx < x + w; xx++) px(im, xx, yy, c); }

    // ------------------------------------------------------------ noise

    static double hash(int x, int y, long s) {
        long h = s * 0x9E3779B97F4A7C15L + x * 0x632BE59BD9B4E019L + y * 0x8CB92BA72F3D8DD7L;
        h ^= h >>> 29; h *= 0xBF58476D1CE4E5B9L; h ^= h >>> 32;
        return (h >>> 11) / (double) (1L << 53);
    }

    static double vnoise(double x, double y, long s) {
        int xi = (int) Math.floor(x), yi = (int) Math.floor(y);
        double fx = x - xi, fy = y - yi;
        fx = fx * fx * (3 - 2 * fx); fy = fy * fy * (3 - 2 * fy);
        double a = hash(xi, yi, s), b = hash(xi + 1, yi, s), c = hash(xi, yi + 1, s), d = hash(xi + 1, yi + 1, s);
        return (a + (b - a) * fx) * (1 - fy) + (c + (d - c) * fx) * fy;
    }

    static double fbm(double x, double y, long s) { return vnoise(x, y, s) * .55 + vnoise(x * 2, y * 2, s + 1) * .3 + vnoise(x * 4, y * 4, s + 2) * .15; }

    // ------------------------------------------------------------ sphere-union shader (trees, rocks, bushes)

    /** Each blob is {cx, cy, r}. Overlapping blobs read as separate lumps because each is lit as its own sphere. */
    static void blobs(BufferedImage im, List<double[]> bl, int[] ramp, long seed, double grain, double bias, int cell) {
        for (int y = 0; y < im.getHeight(); y++)
            for (int x = 0; x < im.getWidth(); x++) {
                double best = -1e9, second = -1e9, nx = 0, ny = 0, nz = 0;
                for (double[] b : bl) {
                    double dx = x + .5 - b[0], dy = y + .5 - b[1], r = b[2];
                    double d2 = dx * dx + dy * dy;
                    if (d2 >= r * r) continue;
                    double hgt = Math.sqrt(r * r - d2);
                    double z = hgt + b[1] * .35;   // lower blobs sit in front
                    if (z > best) { second = best; best = z; nx = dx / r; ny = dy / r; nz = hgt / r; }
                    else if (z > second) second = z;
                }
                if (best < -1e8) continue;
                double lit = nx * LX + ny * LY + nz * LZ;
                double v = .5 + lit * .55 + bias;
                v += (hash(x / cell, y / cell, seed) - .5) * grain;   // leafy / gritty clumps
                if (best - second < 2.2) v -= .14;                      // crevice between lumps
                im.setRGB(x, y, sh(ramp, Math.max(.6, v * (ramp.length - 1))));
            }
    }

    static BufferedImage img(int w, int h) { return new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB); }

    // ------------------------------------------------------------ textures ("blocks")

    static final int[] GRASS = ramp(0x5fae4c, 7), TALL = ramp(0x3d8f3c, 7), DIRT = ramp(0xc9a36d, 7), SAND = ramp(0xe4d29b, 5);
    static final int[] LEAF = ramp(0x4e9d3d, 7), PINE = ramp(0x2f6f4c, 7), BARK = ramp(0x7a5230, 6), STONE = ramp(0x9b978e, 7);
    static final int[] WOOD = ramp(0xc4955c, 6), PLASTER = ramp(0xf0e4cb, 6), ROOF = ramp(0xc8564a, 7), BRICK = ramp(0xb06048, 6);

    static BufferedImage tallGrass(long seed) {
        BufferedImage im = img(T, T);
        for (int row = 0; row < 3; row++) {
            int base = 12 + row * 10;
            for (int i = 0; i < 7; i++) {
                double bx = 1 + i * 5 + hash(i, row, seed) * 3 - (row == 1 ? 2 : 0);
                int hgt = 9 + (int) (hash(i, row + 7, seed) * 6);
                double lean = (hash(i, row + 3, seed) - .5) * 4;
                for (int y = 0; y < hgt; y++) {
                    double t = y / (double) hgt;                // 0 at tip
                    double half = 2.2 * t + .3;
                    double cx = bx + lean * (1 - t);
                    for (int x = (int) Math.floor(cx - half); x <= Math.ceil(cx + half); x++) {
                        if (Math.abs(x + .5 - cx) > half) continue;
                        double v = 1.5 + (1 - t) * 3.4 + row * .6 + (x + .5 < cx ? .7 : -.3);
                        px(im, x, base - hgt + y, sh(TALL, v));
                    }
                }
            }
        }
        PixelCanvas.selOut(im, .35);
        return im;
    }

    static BufferedImage oak(long seed) {
        BufferedImage im = img(64, 96);
        // trunk with flared roots, lit as a cylinder
        for (int y = 56; y < 94; y++) {
            double hw = 6 + (y > 84 ? (y - 84) * .9 : 0);
            for (int x = (int) (32 - hw); x < 32 + hw; x++) {
                double t = (x + .5 - 32) / hw;                      // -1..1
                double v = 3.2 - t * 1.8 + (vnoise(x * .9, y * .12, seed) - .5) * 1.6;
                px(im, x, y, sh(BARK, v));
            }
        }
        List<double[]> crown = List.of(
                new double[] {32, 30, 22}, new double[] {17, 38, 15}, new double[] {47, 38, 15}, new double[] {23, 19, 14},
                new double[] {42, 19, 14}, new double[] {32, 12, 11}, new double[] {32, 47, 16}, new double[] {11, 27, 10},
                new double[] {53, 27, 10}, new double[] {22, 50, 11}, new double[] {43, 50, 11});
        BufferedImage leaves = img(64, 96);
        blobs(leaves, crown, LEAF, seed, .55, -.02, 2);
        // a few light-catching leaf tips on the sunny side
        for (int i = 0; i < 40; i++) {
            int x = (int) (hash(i, 1, seed) * 64), y = (int) (hash(i, 2, seed) * 64);
            if ((leaves.getRGB(x, y) >>> 24) != 0 && x + y < 70) px(leaves, x, y, LEAF[6]);
        }
        Graphics2D g = im.createGraphics();
        g.drawImage(leaves, 0, 0, null);
        g.dispose();
        PixelCanvas.selOut(im, .5);
        return im;
    }

    static BufferedImage pine(long seed) {
        BufferedImage im = img(64, 96);
        rect(im, 28, 76, 8, 18, BARK[2]);
        rect(im, 28, 76, 3, 18, BARK[4]);
        rect(im, 33, 76, 3, 18, BARK[1]);
        List<double[]> tiers = new ArrayList<>();
        for (int i = 0; i < 4; i++) {
            double cy = 72 - i * 15, rx = 26 - i * 5.5, r = 10 - i;
            for (double k = -1; k <= 1.01; k += .5) tiers.add(new double[] {32 + k * rx * .7, cy - Math.abs(k) * 3, r + (1 - Math.abs(k)) * 3});
        }
        tiers.add(new double[] {32, 12, 7});
        BufferedImage n = img(64, 96);
        blobs(n, tiers, PINE, seed, .5, 0, 1);
        Graphics2D g = im.createGraphics();
        g.drawImage(n, 0, 0, null);
        g.dispose();
        PixelCanvas.selOut(im, .5);
        return im;
    }

    static BufferedImage rock(long seed) {
        BufferedImage im = img(T, T);
        blobs(im, List.of(new double[] {16, 21, 10}, new double[] {9, 24, 6.5}, new double[] {23, 23, 7}, new double[] {14, 14, 6.5}), STONE, seed, .35, .05, 1);
        for (int i = 0; i < 6; i++) px(im, 15 + i / 2, 17 + i, STONE[1]); // crack
        PixelCanvas.selOut(im, .5);
        return im;
    }

    static BufferedImage bush(long seed) {
        BufferedImage im = img(T, T);
        blobs(im, List.of(new double[] {16, 20, 11}, new double[] {8, 23, 7}, new double[] {24, 23, 7}, new double[] {12, 13, 6.5}, new double[] {21, 13, 6.5}), LEAF, seed, .5, .02, 2);
        int[][] berries = {{10, 18}, {20, 16}, {16, 24}, {24, 21}};
        for (int[] b : berries) { px(im, b[0], b[1], 0xffe04858); px(im, b[0] + 1, b[1], 0xffb83040); px(im, b[0], b[1] - 1, 0xffff98a0); }
        PixelCanvas.selOut(im, .5);
        return im;
    }

    static BufferedImage fence() {
        BufferedImage im = img(T, T);
        for (int px0 : new int[] {3, 25}) {
            for (int y = 8; y < 31; y++) for (int x = px0; x < px0 + 4; x++) px(im, x, y, sh(WOOD, x == px0 ? 4 : x == px0 + 3 ? 1.5 : 3));
            rect(im, px0, 7, 4, 1, WOOD[5]);
        }
        for (int ry : new int[] {13, 21}) {
            for (int x = 0; x < T; x++) {
                if ((x >= 3 && x < 7) || (x >= 25 && x < 29)) continue;
                px(im, x, ry, WOOD[5]);
                px(im, x, ry + 1, WOOD[3]);
                px(im, x, ry + 2, WOOD[3]);
                px(im, x, ry + 3, WOOD[1]);
            }
        }
        PixelCanvas.selOut(im, .55);
        return im;
    }

    static BufferedImage sign() {
        BufferedImage im = img(T, T);
        rect(im, 14, 18, 4, 13, WOOD[2]);
        rect(im, 14, 18, 1, 13, WOOD[4]);
        for (int y = 4; y < 20; y++)
            for (int x = 3; x < 29; x++) {
                int plank = (y - 4) / 5;
                double v = 3 + (y == 4 + plank * 5 ? 1.5 : 0) - (y == 8 + plank * 5 ? 1.5 : 0) + (vnoise(x * .4, y * 2, 3) - .5);
                px(im, x, y, sh(WOOD, v));
            }
        for (int l = 0; l < 2; l++) rect(im, 8, 9 + l * 5, 16 - l * 5, 2, WOOD[0]);
        PixelCanvas.selOut(im, .55);
        return im;
    }

    static BufferedImage house(long seed) {
        int w = 128, h = 136;
        BufferedImage im = img(w, h);
        int roofTop = 10, roofBot = 66, wallBot = 128;
        // chimney (behind the roof)
        for (int y = 0; y < 34; y++) for (int x = 92; x < 106; x++) {
            boolean mortar = y % 6 == 5 || (x - 92 + (y / 6 % 2) * 4) % 8 == 7;
            px(im, x, y, mortar ? BRICK[1] : sh(BRICK, 3 + (x < 95 ? 1 : x > 102 ? -1 : 0) + (hash(x / 8, y / 6, 9) - .5)));
        }
        rect(im, 90, 0, 18, 3, BRICK[4]);
        // walls: plaster with a timber frame
        for (int y = roofBot; y < wallBot; y++)
            for (int x = 4; x < w - 4; x++) {
                double v = 3 + (fbm(x * .15, y * .15, seed) - .5) * 1.2;
                if (y < roofBot + 9) v -= (roofBot + 9 - y) * .22;   // eave shadow
                px(im, x, y, sh(PLASTER, v));
            }
        for (int x : new int[] {4, 60, w - 8}) for (int y = roofBot; y < wallBot; y++) for (int k = 0; k < 4; k++) px(im, x + k, y, sh(WOOD, 1.5 + (k == 0 ? 1 : 0)));
        // stone foundation
        for (int y = wallBot - 10; y < wallBot; y++)
            for (int x = 4; x < w - 4; x++) {
                int row = (y - (wallBot - 10)) / 5, bx = (x + row * 6) / 12;
                boolean gap = (y - (wallBot - 10)) % 5 == 4 || (x + row * 6) % 12 == 11;
                double v = gap ? 1 : 3 + (hash(bx, row, seed) - .5) * 1.6 + ((y - (wallBot - 10)) % 5 == 0 ? 1 : 0);
                px(im, x, y, sh(STONE, v));
            }
        // windows with flower boxes
        for (int wx : new int[] {16, 84}) {
            rect(im, wx - 2, 80, 32, 30, WOOD[1]);
            for (int y = 82; y < 108; y++)
                for (int x = wx; x < wx + 28; x++) {
                    double t = (y - 82) / 26.0;
                    int glass = mix(0xffcdeaf7, 0xff4f86b8, t * .9);
                    if ((x - wx) + (y - 82) * .6 > 6 && (x - wx) + (y - 82) * .6 < 10) glass = mix(glass, 0xffffffff, .6);
                    if ((x - wx) + (y - 82) * .6 > 13 && (x - wx) + (y - 82) * .6 < 15) glass = mix(glass, 0xffffffff, .35);
                    px(im, x, y, glass);
                }
            rect(im, wx + 13, 82, 2, 26, WOOD[3]);
            rect(im, wx, 94, 28, 2, WOOD[3]);
            rect(im, wx - 3, 108, 34, 3, WOOD[4]);
            for (int y = 111; y < 117; y++) for (int x = wx - 2; x < wx + 30; x++) px(im, x, y, sh(WOOD, y == 111 ? 3 : 2));
            for (int i = 0; i < 9; i++) { // flowers
                int fx = wx + i * 3 + 1, fy = 107 + (int) (hash(i, wx, seed) * 3);
                int c = i % 3 == 0 ? 0xffe8505a : i % 3 == 1 ? 0xfff6d04a : 0xfff3f3f3;
                px(im, fx, fy, c); px(im, fx + 1, fy, c); px(im, fx, fy + 1, mix(c, 0xff000000, .25));
                px(im, fx, fy + 2, 0xff3f8a3a);
            }
        }
        // door
        for (int y = 86; y < wallBot; y++)
            for (int x = 52; x < 76; x++) {
                boolean frame = x < 54 || x > 73 || y < 88;
                double v = frame ? 1.5 : 2.6 + ((x - 54) % 5 == 0 ? -1 : 0) + (x < 58 ? .6 : 0);
                px(im, x, y, sh(WOOD, v));
            }
        for (int y = 90; y < 98; y++) for (int x = 58; x < 70; x++) px(im, x, y, mix(0xffcdeaf7, 0xff6f9fc8, (y - 90) / 8.0));
        px(im, 70, 110, 0xfff8d860); px(im, 71, 110, 0xffc89a30); px(im, 70, 111, 0xffc89a30);
        rect(im, 48, wallBot, 32, 4, STONE[4]);
        rect(im, 48, wallBot + 4, 32, 2, STONE[2]);
        // roof: overlapping shingle rows, lighter toward the top, with a ridge cap
        for (int y = roofTop; y < roofBot; y++) {
            double f = (y - roofTop) / (double) (roofBot - roofTop);
            int inset = (int) ((1 - f) * 8);
            int row = (y - roofTop) / 7, ry = (y - roofTop) % 7;
            for (int x = inset; x < w - inset; x++) {
                int col = (x + (row % 2) * 8) / 16, cx = (x + (row % 2) * 8) % 16;
                double v = 3.4 - f * 1.2 + (hash(col, row, seed) - .5) * 1.2;
                if (ry == 0) v += 1.6;
                if (ry == 6) v -= 2;
                if (cx == 15) v -= 1.4;
                if (x < inset + 2 || x > w - inset - 3) v -= 1.2;
                px(im, x, y, sh(ROOF, v));
            }
        }
        for (int x = 8; x < w - 8; x++) { px(im, x, roofTop - 2, ROOF[5]); px(im, x, roofTop - 1, ROOF[4]); px(im, x, roofTop, ROOF[2]); }
        for (int x = 0; x < w; x++) { px(im, x, roofBot, WOOD[1]); px(im, x, roofBot + 1, WOOD[0]); }
        PixelCanvas.selOut(im, .6);
        // smoke
        for (int i = 0; i < 3; i++) for (int y = -6; y <= 6; y++) for (int x = -6; x <= 6; x++) {
            double d = Math.sqrt(x * x + y * y) / (5 - i);
            if (d < 1) blend(im, 99 + x - i * 4, -2 - i * 8 + y + 4, 0xfff4f4f4, (1 - d) * .55);
        }
        return im;
    }

    // ------------------------------------------------------------ characters (32x48)

    static BufferedImage character(int skin, int hair, int cap, int jacket, int pants, boolean longHair) {
        BufferedImage im = img(32, 48);
        int[] S = ramp(skin, 5), Hh = ramp(hair, 5), C = ramp(cap, 5), J = ramp(jacket, 5), P = ramp(pants, 5), SH = ramp(0x3a3a46, 5);
        if (longHair) for (int y = 12; y < 30; y++) for (int x = 6; x < 26; x++) if (Math.abs(x + .5 - 16) < 9.5 - (y > 24 ? (y - 24) * .5 : 0)) px(im, x, y, sh(Hh, x < 16 ? 2.5 : 1.5));
        for (int y = 34; y < 44; y++) { rect(im, 10, y, 5, 1, P[y < 36 ? 3 : 2]); rect(im, 17, y, 5, 1, P[1]); px(im, 16, y, P[0]); }
        for (int y = 43; y < 48; y++) { int v = y == 43 ? 4 : y == 47 ? 0 : 2; rect(im, 9, y, 7, 1, SH[v]); rect(im, 17, y, 7, 1, SH[Math.max(0, v - 1)]); }
        for (int y = 22; y < 36; y++) for (int x = 8; x < 24; x++) {
            if ((y == 22 || y == 35) && (x == 8 || x == 23)) continue;
            px(im, x, y, sh(J, x < 11 ? 4 : x < 20 ? 3 : 2) );
        }
        for (int y = 24; y < 35; y++) px(im, 16, y, J[1]);
        rect(im, 12, 22, 9, 2, 0xfff4f4f4);
        for (int y = 23; y < 34; y++) { rect(im, 5, y, 3, 1, J[y < 25 ? 4 : 3]); rect(im, 24, y, 3, 1, J[1]); }
        rect(im, 5, 34, 3, 2, S[3]); rect(im, 24, 34, 3, 2, S[1]);
        for (int y = 22; y < 30; y++) { px(im, 11, y, 0xff5a3a2a); px(im, 21, y, 0xff5a3a2a); }   // backpack straps
        for (int y = 6; y < 23; y++) for (int x = 7; x < 26; x++) {   // head, lit like a sphere
            double dx = (x + .5 - 16.5) / 8.6, dy = (y + .5 - 14.5) / 8.2;
            double d = dx * dx + dy * dy;
            if (d > 1) continue;
            double nz = Math.sqrt(1 - d);
            double v = 2 + (dx * LX + dy * LY + nz * LZ) * 2.6;
            px(im, x, y, sh(S, v));
        }
        for (int y = 3; y < 15; y++) for (int x = 6; x < 27; x++) {   // hair
            double dx = (x + .5 - 16.5) / 10.2, dy = (y + .5 - 11) / 7.6;
            int fringe = cap != 0 ? 11 : 8 + (x % 3 == 0 ? 1 : 0);   // bangs end above the eyes
            if (dx * dx + dy * dy > 1 || (y > fringe && x > 9 && x < 24)) continue;
            double v = 2.6 - dx * 1.2 - dy + ((x + y) % 4 == 0 ? -1 : 0);
            px(im, x, y, sh(Hh, v));
        }
        if (cap != 0) {
            for (int y = 2; y < 11; y++) for (int x = 7; x < 26; x++) {
                double dx = (x + .5 - 16.5) / 9.5, dy = (y + .5 - 10) / 8;
                if (dx * dx + dy * dy > 1) continue;
                px(im, x, y, sh(C, 3 - dx * 1.4 - dy * .8));
            }
            for (int x = 6; x < 27; x++) { px(im, x, 10, C[1]); px(im, x, 11, C[0]); }
            rect(im, 15, 4, 3, 3, 0xfff4f4f4);
        }
        for (int ex : new int[] {11, 19}) {
            rect(im, ex, 15, 3, 4, 0xfff8f8f8);
            rect(im, ex + 1, 16, 2, 3, 0xff20202a);
            px(im, ex + 1, 16, 0xfff8f8f8);
        }
        rect(im, 15, 20, 3, 1, mix(S[1], 0xff803030, .4));
        blend(im, 10, 19, 0xffff7088, .45); blend(im, 22, 19, 0xffff7088, .45);
        PixelCanvas.selOut(im, .55);
        return im;
    }

    // ------------------------------------------------------------ the sample scene

    static final String[] MAP = {
            "ggggggggppgggg.",
            "ggggggggppggggg",
            "ggggggggppggggg",
            "ggggggggppgggww",
            "pppppppppppgwww",
            "pppppppppppgwww",
            "ggtttggggppggww",
            "gttttttggppgggg",
            "gttttttggppffgg",
            "ggtttggggppffgg"};

    static char tileAt(int tx, int ty) {
        tx = Math.max(0, Math.min(14, tx));
        ty = Math.max(0, Math.min(9, ty));
        char c = MAP[ty].charAt(tx);
        return c == '.' ? 'g' : c;
    }

    /** Smooth 0..1 field of how much a material is present, interpolated between tile centres plus noise: gives organic edges without 47 hand-made edge tiles. */
    static double field(int x, int y, char m, long seed) {
        double u = x / (double) T - .5, v = y / (double) T - .5;
        int i0 = (int) Math.floor(u), j0 = (int) Math.floor(v);
        double fx = u - i0, fy = v - j0;
        fx = fx * fx * (3 - 2 * fx); fy = fy * fy * (3 - 2 * fy);
        double a = tileAt(i0, j0) == m ? 1 : 0, b = tileAt(i0 + 1, j0) == m ? 1 : 0, c = tileAt(i0, j0 + 1) == m ? 1 : 0, d = tileAt(i0 + 1, j0 + 1) == m ? 1 : 0;
        double f = (a + (b - a) * fx) * (1 - fy) + (c + (d - c) * fx) * fy;
        return f + (fbm(x * .09, y * .09, seed) - .5) * .32;
    }

    static BufferedImage ground(long seed) {
        BufferedImage im = new BufferedImage(W, H, BufferedImage.TYPE_INT_ARGB);
        for (int y = 0; y < H; y++)
            for (int x = 0; x < W; x++) {
                double fp = field(x, y, 'p', seed), fw = field(x, y, 'w', seed + 5);
                int c;
                if (fw > .5) {
                    double depth = Math.min(1, (fw - .5) * 2.6);
                    c = mix(0xff73c6ea, 0xff2e6cb6, depth);
                    double wave = Math.sin(x * .22 + y * .7 + fbm(x * .05, y * .05, seed) * 6);
                    if (wave > .93) c = mix(c, 0xffffffff, .55);
                    if (fw < .55) c = mix(0xffeaf7ff, c, (fw - .5) / .05 * .6);           // foam
                } else if (fw > .42) {
                    c = sh(SAND, 2 + (fw - .42) * 15 * -.1 + (hash(x, y, seed) - .5) * 1.2);   // wet sand rim
                    if (fw > .48) c = mix(c, 0xff8f7f60, .35);
                } else if (fp > .5) {
                    double v = 3 + (fbm(x * .12, y * .12, seed + 2) - .5) * 1.6;
                    if (fp < .56) v -= 1.2;                                                     // worn rim
                    c = sh(DIRT, v);
                } else {
                    double v = 3 + (fbm(x * .03, y * .03, seed + 3) - .5) * 2.2 + (hash(x / 2, y / 2, seed) - .5) * .8;
                    if (fp > .43) v -= (fp - .43) * 14;                                        // grass darkens next to the path
                    c = sh(GRASS, v);
                }
                im.setRGB(x, y, c);
            }
        // pebbles in the dirt, blades and flowers on the grass
        for (int y = 2; y < H; y++)
            for (int x = 1; x < W - 1; x++) {
                double r = hash(x, y, seed + 9);
                double fp = field(x, y, 'p', seed), fw = field(x, y, 'w', seed + 5);
                if (fp > .58 && fw < .4 && r > .992) {
                    px(im, x, y, DIRT[5]); px(im, x + 1, y, DIRT[4]); px(im, x, y + 1, DIRT[1]); px(im, x + 1, y + 1, DIRT[1]);
                } else if (fp < .52 && fw < .4 && r > .955) {
                    px(im, x, y, GRASS[1]);
                    px(im, x, y - 1, GRASS[4]);
                    px(im, x + (r > .98 ? 1 : -1), y - 2, GRASS[5]);
                }
                if (tileAt(x / T, y / T) == 'f' && r > .993) {
                    int col = r > .997 ? 0xffe8505a : r > .995 ? 0xfff6d04a : 0xfff6f6f6;
                    px(im, x - 1, y, col); px(im, x + 1, y, col); px(im, x, y - 1, col); px(im, x, y + 1, mix(col, 0xff000000, .3));
                    px(im, x, y, 0xfff8e070);
                }
            }
        return im;
    }

    static void shadow(BufferedImage im, double cx, double cy, double rx, double ry, double a) {
        for (int y = (int) (cy - ry); y <= cy + ry; y++)
            for (int x = (int) (cx - rx); x <= cx + rx; x++) {
                double dx = (x + .5 - cx) / rx, dy = (y + .5 - cy) / ry, d = Math.sqrt(dx * dx + dy * dy);
                if (d < 1) blend(im, x, y, 0xff1c2a3a, a * Math.min(1, (1 - d) * 3));
            }
    }

    static void draw(Graphics2D g, BufferedImage s, int x, int y) { g.drawImage(s, x, y, null); }

    static BufferedImage scene() {
        long seed = 7;
        BufferedImage im = ground(seed);
        BufferedImage oak = oak(3), pine = pine(4), house = house(5), tall = tallGrass(6), rock = rock(8), bush = bush(9), fence = fence(), sign = sign();
        BufferedImage player = character(0xf2c49e, 0x4a2c1c, 0xd8423e, 0x3a6fd0, 0x3c4458, false);
        BufferedImage npc = character(0xc98a5e, 0x26304a, 0, 0xe8a53a, 0x5a4a3e, true);
        // contact shadows first, so every object sits on the ground
        shadow(im, 3 * T + 4, 4 * T - 2, 70, 9, .45);         // house
        shadow(im, 11 * T + 4, 2 * T + 28, 26, 7, .5);        // oak
        shadow(im, 13 * T + 6, 2 * T + 30, 24, 7, .5);        // pine
        shadow(im, 7 * T + 18, 5 * T + 30, 12, 4, .45);       // player
        shadow(im, 4 * T + 18, 5 * T + 30, 12, 4, .45);       // npc
        shadow(im, 12 * T + 16, 8 * T + 30, 13, 4, .45);      // rock
        shadow(im, 0 * T + 18, 3 * T + 30, 14, 4, .4);        // bush
        Graphics2D g = im.createGraphics();
        for (int ty = 0; ty < 10; ty++) for (int tx = 0; tx < 15; tx++) if (MAP[ty].charAt(tx) == 't') draw(g, tall, tx * T, ty * T);
        // back to front by base line
        draw(g, house, 1 * T, 4 * T - 136);
        draw(g, oak, 10 * T + 4 - 16, 3 * T - 96);
        draw(g, pine, 12 * T + 6 - 16, 3 * T - 96);
        draw(g, bush, 0, 3 * T);
        draw(g, sign, 6 * T, 3 * T);
        for (int x = 9; x <= 10; x++) draw(g, fence, x * T, 6 * T);
        draw(g, npc, 4 * T, 5 * T + 32 - 48);
        draw(g, player, 7 * T, 5 * T + 32 - 48);
        draw(g, rock, 12 * T, 8 * T);
        // modern UI: soft translucent panels, crisp 2x text
        panel(g, 10, 10, Font.width("Hollowford Town") * 2 + 28, 26, 13);
        Font.raw(g, "Hollowford Town", 24, 16, new Color(0x2a2a30), 2);
        Font.raw(g, "Hollowford Town", 23, 15, Color.WHITE, 2);
        panel(g, 16, 236, W - 32, 72, 14);
        g.setColor(new Color(0xf0a040));
        g.fillRoundRect(28, 226, Font.width("Mom") * 2 + 20, 20, 10, 10);
        Font.raw(g, "Mom", 38, 229, Color.WHITE, 2);
        List<String> lines = Font.wrap("The world outside looks so much sharper today! Go say hi to Professor Alder.", 200);
        for (int i = 0; i < Math.min(2, lines.size()); i++) {
            Font.raw(g, lines.get(i), 37, 257 + i * 22, new Color(0x10141e), 2);
            Font.raw(g, lines.get(i), 36, 256 + i * 22, new Color(0xf4f6fb), 2);
        }
        g.setColor(new Color(0xf0a040));
        g.fillPolygon(new int[] {W - 40, W - 28, W - 34}, new int[] {290, 290, 297}, 3);
        g.dispose();
        return im;
    }

    static void panel(Graphics2D g, int x, int y, int w, int h, int r) {
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setColor(new Color(0, 0, 0, 60));
        g.fillRoundRect(x + 2, y + 4, w, h, r * 2, r * 2);
        g.setColor(new Color(22, 30, 52, 225));
        g.fillRoundRect(x, y, w, h, r * 2, r * 2);
        g.setColor(new Color(255, 255, 255, 200));
        g.setStroke(new BasicStroke(2f));
        g.drawRoundRect(x + 1, y + 1, w - 2, h - 2, r * 2 - 2, r * 2 - 2);
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
    }

    // ------------------------------------------------------------ outputs

    static BufferedImage scale(BufferedImage src, int s) {
        BufferedImage o = new BufferedImage(src.getWidth() * s, src.getHeight() * s, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = o.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
        g.drawImage(src, 0, 0, o.getWidth(), o.getHeight(), null);
        g.dispose();
        return o;
    }

    static BufferedImage atlas() {
        BufferedImage ground = ground(7);
        Object[][] items = {
                {"grass", ground.getSubimage(14 * T, 7 * T, T, T)},
                {"tall_grass", tallGrass(6)},
                {"dirt_path", ground.getSubimage(8 * T, 1 * T, T, T)},
                {"path_edge", ground.getSubimage(9 * T, 3 * T, T, T)},
                {"water", ground.getSubimage(13 * T, 4 * T, T, T)},
                {"shore", ground.getSubimage(11 * T, 4 * T, T, T)},
                {"flowers", ground.getSubimage(11 * T, 8 * T, T, T)},
                {"fence", fence()},
                {"sign", sign()},
                {"rock", rock(8)},
                {"berry_bush", bush(9)},
                {"oak_tree", oak(3)},
                {"pine_tree", pine(4)},
                {"house", house(5)},
                {"player", character(0xf2c49e, 0x4a2c1c, 0xd8423e, 0x3a6fd0, 0x3c4458, false)},
                {"villager", character(0xc98a5e, 0x26304a, 0, 0xe8a53a, 0x5a4a3e, true)}};
        int s = 2, cellW = 140, x = 10, y = 30, rowH = 0;
        BufferedImage out = new BufferedImage(900, 620, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = out.createGraphics();
        g.setColor(new Color(0x23262e));
        g.fillRect(0, 0, out.getWidth(), out.getHeight());
        Font.raw(g, "textures/block/  (baked from code, editable like a Minecraft resource pack)", 10, 8, new Color(0xd8dbe4), 2);
        for (Object[] it : items) {
            BufferedImage im = (BufferedImage) it[1];
            int w = Math.max(cellW, im.getWidth() * s + 10);
            if (x + w > out.getWidth()) { x = 10; y += rowH + 26; rowH = 0; }
            g.setColor(new Color(0x2e323c));
            g.fillRect(x, y, im.getWidth() * s, im.getHeight() * s);
            g.drawImage(scale(im, s), x, y, null);
            Font.raw(g, it[0] + ".png", x, y + im.getHeight() * s + 6, new Color(0xa8adbb), 1);
            x += w;
            rowH = Math.max(rowH, im.getHeight() * s);
        }
        g.dispose();
        return out;
    }

    public static void main(String[] args) throws Exception {
        File out = new File(args[0]);
        out.mkdirs();
        BufferedImage sc = scene();
        ImageIO.write(scale(sc, 2), "png", new File(out, "hd_scene.png"));
        ImageIO.write(atlas(), "png", new File(out, "hd_atlas.png"));
        if (args.length > 1) { // side by side with the current game frame (given at 3x)
            BufferedImage cur = ImageIO.read(new File(args[1]));
            BufferedImage small = new BufferedImage(240, 160, BufferedImage.TYPE_INT_RGB);
            small.getGraphics().drawImage(cur, 0, 0, 240, 160, null);
            BufferedImage cmp = new BufferedImage(960 * 2 + 20, 640 + 40, BufferedImage.TYPE_INT_RGB);
            Graphics2D g = cmp.createGraphics();
            g.setColor(new Color(0x23262e));
            g.fillRect(0, 0, cmp.getWidth(), cmp.getHeight());
            g.drawImage(scale(small, 4), 0, 40, null);
            g.drawImage(scale(sc, 2), 980, 40, null);
            Font.raw(g, "NOW: 240x160, 16px tiles, GBA colors", 10, 10, Color.WHITE, 3);
            Font.raw(g, "PROPOSAL: 480x320, 32px tiles, full color", 990, 10, Color.WHITE, 3);
            g.dispose();
            ImageIO.write(cmp, "png", new File(out, "hd_compare.png"));
        }
        System.out.println("ok");
    }
}
